class WorkstationScannerNotifier extends StateNotifier<ScannerState> {
  final AgoraRtcEngine _rtcEngine;
  final HiveBox<TaskModel> _taskCache;

  Future<void> claimTaskByQr(String qrCode) async {
    // First-scan-wins smart assignment
