export const getRecommendations = async (userPreferences, watchlist) => {
  const genres = watchlist.map(m => m.genre_ids).flat();
  const response = await api.get('/discover/movie', {
    params: {
      with_genres: [...new Set(genres)].join(','),
      sort_by: 'popularity.desc',
      vote_count_gte: 100
    }
  });
  return response.data.results;
};

